        n1 = {"n2", "n3"},
        n2 = {"n4", "n5"},
        n3 = {"n5", "n6"},
        n4 = {"n7"},
        n5 = {"n7", "n8"},
        n6 = {"n8"},
        n7 = {"n9"},
        n8 = {"n9", "n10"},
        n9 = {"n10"},
        n10 = {}
    }
    return nodeConnections[nodeId] or ({})
end
function AutoChessMode.prototype.sendStageUnlockUpdate(self)
    print("[AutoChessMode] ========== 开始发送关卡解锁更新 ==========")
    local nodes = {}
    local allNodeIds = {
        "n1",
        "n2",
        "n3",
        "n4",
        "n5",
        "n6",
        "n7",
        "n8",
        "n9",
        "n10"
    }
    for ____, nodeId in ipairs(allNodeIds) do
        local status = "locked"
        if self.completedStages:has(nodeId) then
            status = "completed"
        elseif self.availableStages:has(nodeId) then
            status = "available"
        end
        nodes[#nodes + 1] = {id = nodeId, status = status}
    end
    local completedArray = {}
    self.completedStages:forEach(function(____, value)
        completedArray[#completedArray + 1] = value
    end)
    local availableArray = {}
    self.availableStages:forEach(function(____, value)
        availableArray[#availableArray + 1] = value
    end)
    print((("[AutoChessMode] 已完成关卡数量: " .. tostring(self.completedStages.size)) .. ", 数组长度: ") .. tostring(#completedArray))
    print((("[AutoChessMode] 可用关卡数量: " .. tostring(self.availableStages.size)) .. ", 数组长度: ") .. tostring(#availableArray))
    print("[AutoChessMode] 节点数量: " .. tostring(#nodes))
    print("[AutoChessMode] 节点状态详情:")
    for ____, node in ipairs(nodes) do
        print((("[AutoChessMode]   - " .. tostring(node.id)) .. ": ") .. tostring(node.status))
    end
    print("[AutoChessMode] 已完成关卡列表: " .. table.concat(completedArray, ", "))
    print("[AutoChessMode] 可用关卡列表: " .. table.concat(availableArray, ", "))
    local updateData = {
        currentStage = self.completedStages.size,
        maxStages = 10,
        nodes = nodes,
        completedStages = completedArray,
        availableStages = availableArray
    }
    print("[AutoChessMode] 📤 准备发送数据...")
    CustomGameEventManager:Send_ServerToAllClients("update_stage_data", updateData)
    print("[AutoChessMode] ✅ 数据已发送")
end
function AutoChessMode.prototype.getStageDescription(self, config)
    local typeNames = {
        normal_battle = "普通战斗",
        elite_battle = "精英战斗",
        event = "事件",
        event_evacuate = "事件/撤离",
        boss = "Boss"
    }
    local typeName = typeNames[config.primaryNodeType] or config.primaryNodeType
    local monsterCount = StageConfigManager:rollMonsterCount(config.stageId)
    local totalCount = monsterCount.normalCount + (monsterCount.specialCount or 0)
    return ((tostring(typeName) .. " | 怪物数量: ") .. tostring(totalCount)) .. "个"
end
function AutoChessMode.prototype.handleWaveStageSelection(self, playerId, stageId)
    local nodeId = self:stageIdToNodeId(stageId)
    if not nodeId or not self.availableStages:has(nodeId) then
        print((("[AutoChessMode] ERROR: 关卡未解锁或无效 - stageId: " .. stageId) .. ", nodeId: ") .. nodeId)
        print("[AutoChessMode] 可用关卡: " .. table.concat(
            __TS__ArrayFrom(self.availableStages),
            ", "
        ))
        CustomGameEventManager:Send_ServerToPlayer(
            PlayerResource:GetPlayer(playerId),
            "autochess_wave_stage_ack",
            {stageId = stageId, success = false, message = "关卡未解锁，请先完成前置关卡"}
        )
        return
    end
    local stageIdNum = __TS__ParseInt(stageId)
    local stageConfig = StageConfigManager:getStageConfig(stageIdNum)
    if not stageConfig then
        print("[AutoChessMode] ERROR: 无效的关卡ID: " .. stageId)
        CustomGameEventManager:Send_ServerToPlayer(
            PlayerResource:GetPlayer(playerId),
            "autochess_wave_stage_ack",
            {stageId = stageId, success = false, message = "无效的关卡ID"}
        )
        return
    end
    print("[AutoChessMode] ========== 玩家选择关卡 ==========")
    print(((((("[AutoChessMode] Player " .. tostring(playerId)) .. " selected stage: ") .. stageId) .. " (") .. stageConfig.primaryNodeType) .. ")")
    if self.phaseTimer then
        Timers:RemoveTimer(self.phaseTimer)
        self.phaseTimer = nil
        print("[AutoChessMode] 已停止当前阶段计时器")
    end
    self:stopAllBattles()
    print("[AutoChessMode] 已清理所有棋子（包括玩家棋子），新关卡时会重新创建")
    self:resetWaveSettlementState()
    self.currentWaveStageSelection = stageId
    print("[AutoChessMode] 📝 已设置 currentWaveStageSelection = " .. self.currentWaveStageSelection)
    CustomGameEventManager:Send_ServerToAllClients("autochess_wave_stage_ack", {
        playerId = playerId,
        stageId = stageId,
        success = true,
        stageName = "关卡" .. stageId,
        stageType = stageConfig.primaryNodeType,
        message = ("已选择关卡" .. stageId) .. "，准备开始..."
    })
    print("[AutoChessMode] 开始5秒准备阶段...")
    self:startPreparationCountdown(playerId, stageIdNum)
end
function AutoChessMode.prototype.startPreparationCountdown(self, playerId, stageId)
    local PREP_TIME = 5
    local timeLeft = PREP_TIME
    CustomGameEventManager:Send_ServerToAllClients("autochess_preparation_started", {timeLeft = timeLeft, stageId = stageId})
    print(("[AutoChessMode] 创建准备阶段倒计时计时器，初始时间: " .. tostring(timeLeft)) .. "秒")
    local countdownTimer = Timers:CreateTimer(
        1,
        function()
            timeLeft = timeLeft - 1
            print(((((("[AutoChessMode] 准备阶段倒计时: " .. tostring(timeLeft)) .. "秒 (stageId: ") .. tostring(stageId)) .. ", playerId: ") .. tostring(playerId)) .. ")")
            CustomGameEventManager:Send_ServerToAllClients("autochess_preparation_countdown", {timeLeft = timeLeft, stageId = stageId})
            if timeLeft <= 0 then
                print("[AutoChessMode] ========== 准备阶段结束，开始生成怪物并战斗 ==========")
                print(((("[AutoChessMode] 调用 startBattleWithStage(playerId: " .. tostring(playerId)) .. ", stageId: ") .. tostring(stageId)) .. ")")
                self:startBattleWithStage(playerId, stageId)
                return nil
            end
            return 1
        end
    )
    if not countdownTimer then
        print("[AutoChessMode] ❌ 错误：倒计时计时器创建失败！")
    else
        print("[AutoChessMode] ✅ 倒计时计时器创建成功")
    end
end
function AutoChessMode.prototype.startBattleWithStage(self, playerId, stageId)
    print("[AutoChessMode] ========== 单机模式 - 开始战斗 ==========")
    print("[AutoChessMode] 使用关卡: " .. tostring(stageId))
    print("[AutoChessMode] 选关前回合: " .. tostring(self.gameState.currentRound))
    local ____self_gameState_14, ____currentRound_15 = self.gameState, "currentRound"
    ____self_gameState_14[____currentRound_15] = ____self_gameState_14[____currentRound_15] + 1
    self.gameState.currentPhase = ____exports.RoundPhase.BATTLE
    self.gameState.phaseTimeLeft = 45
    self.gameState.isGameActive = true
    print("[AutoChessMode] 选关后回合: " .. tostring(self.gameState.currentRound))
    print("[AutoChessMode] 当前阶段: " .. self.gameState.currentPhase)
    self.battleSystem:clearPlayerPieces(-1)
    for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
        local pid = ____value[1]
        local playerState = ____value[2]
        playerState.isAlive = true
        print(("[AutoChessMode] 玩家 " .. tostring(pid)) .. " 进入新关卡，准备重新创建棋子")
    end
    print("[AutoChessMode] 重新创建玩家棋子...")
    for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
        local pid = ____value[1]
        local playerState = ____value[2]
        if playerState.isAlive then
            self.battleSystem:setPlayerAsProtected(pid)
            self:recreatePlayerPieces(pid)
            print(("[AutoChessMode] 玩家 " .. tostring(pid)) .. " 棋子已重新创建")
        end
    end
    print(("[AutoChessMode] 根据关卡 " .. tostring(stageId)) .. " 配置生成敌人...")
    for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
        local pid = ____value[1]
        local playerState = ____value[2]
        if playerState.isAlive then
            self:createEnemyForPlayer(pid, stageId)
        end
    end
    self:startAllBattles()
    self:startPhaseTimer()
    self:syncStateToNetTable()
    CustomGameEventManager:Send_ServerToAllClients("autochess_battle_started", {stageId = stageId, round = self.gameState.currentRound, timeLeft = self.gameState.phaseTimeLeft})
    print("[AutoChessMode] ========== 战斗已开始 ==========")
end
return ____exports
